package com.wartec.flightqa;

import com.google.gson.*;
import com.mojang.authlib.GameProfile;
import com.wartec.wartecmod.port.content.*;
import com.wartec.wartecmod.port.entity.*;
import com.wartec.wartecmod.port.gameplay.*;
import com.wartec.wartecmod.port.integration.*;
import com.wartec.wartecmod.port.network.MissileTrackingService;
import com.wartec.wartecmod.port.planning.*;
import com.wartec.wartecmod.port.silo.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import net.minecraft.entity.Entity;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.*;
import net.minecraft.util.math.*;
import net.minecraft.world.WorldServer;
import net.minecraftforge.common.*;
import net.minecraftforge.common.util.FakePlayer;
import net.minecraftforge.fml.common.FMLCommonHandler;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import net.minecraftforge.fml.common.gameevent.TickEvent;
import net.minecraftforge.event.entity.EntityJoinWorldEvent;

/** Actual moving targets, native radar and lid, automatic admission and recorded outcomes. */
public final class SiloAbmQa {
    private WorldServer world;private FakePlayer owner,enemy;private int tick;private EntityModernVehicle radar;
    private final List<TileEntityMissileSilo> cores=new ArrayList<>();private final List<ForgeChunkManager.Ticket> pins=new ArrayList<>();
    private final List<EntitySiloInterceptor> shots=new ArrayList<>();private final List<EntityStrategicMissile> targets=new ArrayList<>();private EntityStrategicMissile blind,mobileBoost,mobileReentry;private EntityStrategicTel tel;private boolean mobileEntryHeight;
    private final JsonArray cases=new JsonArray(),trace=new JsonArray();private final List<String> failures=new ArrayList<>();
    private final BlockPos anchor=new BlockPos(36008,80,36008);
    private void check(String key,boolean ok,Object detail){JsonObject row=new JsonObject();row.addProperty("kind",key);row.addProperty("success",ok);row.addProperty("detail",String.valueOf(detail));cases.add(row);if(!ok)failures.add(key+": "+detail);System.out.println("SILOABMQA "+row);}
    public void started(){if(!Files.isRegularFile(Paths.get("FLIGHT_QA_ISOLATED")))throw new IllegalStateException("Not isolated");world=FMLCommonHandler.instance().getMinecraftServerInstance().getWorld(0);world.getGameRules().setOrCreateGameRule("doMobSpawning","false");MinecraftForge.EVENT_BUS.register(this);}
    private void pin(int x,int z){ForgeChunkManager.Ticket ticket=ForgeChunkManager.requestTicket(com.wartec.wartecmod.WarTechReforged.instance,world,ForgeChunkManager.Type.NORMAL);pins.add(ticket);for(int cx=-2;cx<=2;cx++)for(int cz=-2;cz<=2;cz++){ChunkPos c=new ChunkPos((x>>4)+cx,(z>>4)+cz);world.getChunkFromChunkCoords(c.x,c.z);ForgeChunkManager.forceChunk(ticket,c);}}
    private void setup(){owner=new FakePlayer(world,new GameProfile(new UUID(107,1),"SiloABMBlue"));enemy=new FakePlayer(world,new GameProfile(new UUID(107,2),"SiloABMRed"));NetworkTeamHelper.setPlayerTeam(owner,"abm-blue");NetworkTeamHelper.setPlayerTeam(enemy,"abm-red");owner.capabilities.isCreativeMode=true;
        for(int x=0;x<=400;x+=64)pin(anchor.getX()+x,anchor.getZ());pin(anchor.getX()+80,anchor.getZ()+48);
        for(int index=0;index<2;index++){BlockPos at=anchor.add(0,0,index*32);pin(at.getX(),at.getZ());for(SiloStructure.Cell cell:SiloStructure.cells(EnumFacing.SOUTH))world.setBlockState(at.add(cell.x,cell.y,cell.z),cell.state,2);
            check("native_hatch_"+index,HbmSiloHatch.place(world,at,EnumFacing.NORTH,owner),"original HBM animation");TileEntityMissileSilo c=(TileEntityMissileSilo)world.getTileEntity(at.down(26));c.claim(owner);c.anchor=at;c.builtStructure=true;c.hatchPos=HbmSiloHatch.controller(at,EnumFacing.NORTH);c.setPower(1_000_000);c.setInventorySlotContents(0,new ItemStack(WarTechContent.SILO_INTERCEPTOR));cores.add(c);
            check("defense_slot_"+index,c.isDefenseMissile(),c.getStackInSlot(0));check("foreign_duty_denied_"+index,!c.setDefenseEnabled(enemy,true),"strict ownership");check("duty_admitted_"+index,c.setDefenseEnabled(owner,true),c.status);check("no_attack_launch_"+index,!c.beginLaunch(owner),c.status);
            PlanningAsset a=PlanningAssetRegistry.describe(c);check("defense_terminal_"+index,a.defense && !a.attack && a.tier==4 && a.ammo==1 && a.range==1600,a.write());
            NBTTagCompound n=c.writeToNBT(new NBTTagCompound());TileEntityMissileSilo copy=new TileEntityMissileSilo();copy.readFromNBT(n);check("duty_nbt_"+index,copy.isDefenseEnabled() && copy.getStackInSlot(0).getItem()==WarTechContent.SILO_INTERCEPTOR,"state survives roundtrip");}
        EntityStrategicMissile mobile=new EntityStrategicMissile(world);mobile.configureReentry(StrategicSystemProfile.TOPOL_M,0,anchor.getX(),80,anchor.getZ(),enemy.getUniqueID(),"abm-red");check("mobile_origin_included",SiloDefense.eligible(mobile),"TEL and silo are both eligible");mobile.setSiloOrigin(true);check("silo_origin_included",SiloDefense.eligible(mobile),"positive origin");mobile.beginCombatCrash();check("debris_excluded",!SiloDefense.eligible(mobile),"crashing debris is not another target");
        EntityStrategicMissile other=new EntityStrategicMissile(world);other.configureReentry(StrategicSystemProfile.ISKANDER,0,0,80,0,enemy.getUniqueID(),"abm-red");other.setSiloOrigin(true);check("iskander_excluded",!SiloDefense.eligible(other),"only Topol/Oreshnik");check("aircraft_excluded",!SiloDefense.eligible(new EntityWarTechAircraft(world)),"not a general SAM");
    }
    private EntityStrategicMissile incoming(StrategicSystemProfile system,String team,int offset){EntityStrategicMissile target=new EntityStrategicMissile(world);target.configureReentry(system,0,anchor.getX()+80,80,anchor.getZ()+offset,enemy.getUniqueID(),team);target.setSiloOrigin(system==StrategicSystemProfile.ORESHNIK && offset==32);target.setPosition(anchor.getX()+300,750,anchor.getZ()+offset);check("incoming_"+tick+"_"+offset,MissileChunkLoader.spawnFlight(target),system+" silo="+target.isSiloOrigin());return target;}
    @SubscribeEvent public void joined(EntityJoinWorldEvent e){if(e.getWorld()==world && e.getEntity() instanceof EntitySiloInterceptor)shots.add((EntitySiloInterceptor)e.getEntity());if(e.getWorld()==world && tick>1100 && e.getEntity() instanceof EntityStrategicMissile){EntityStrategicMissile m=(EntityStrategicMissile)e.getEntity();if(m.isReentryVehicle()){mobileReentry=m;mobileEntryHeight=m.posY>=900;}else mobileBoost=m;}}
    @SubscribeEvent public void tick(TickEvent.ServerTickEvent e)throws Exception{if(e.phase!=TickEvent.Phase.END)return;tick++;
        if(tick==1)setup();
        if(tick==10)blind=incoming(StrategicSystemProfile.TOPOL_M,"abm-red",0);
        if(tick==50){check("no_radar_no_shot",shots.isEmpty() && cores.stream().allMatch(c->c.phase==0),"hostile live silo warhead, no radar");blind.setDead();radar=new EntityModernVehicle(world,ModernVehicleProfile.RADAR_9S18);radar.setOwnerIdentity(owner.getUniqueID(),"abm-blue");radar.setPosition(anchor.getX()+100,80,anchor.getZ()+90);pin((int)radar.posX,(int)radar.posZ);pin(anchor.getX()+150,anchor.getZ()+60);pin(anchor.getX()+225,anchor.getZ()+30);for(int x=-5;x<=5;x++)for(int z=-5;z<=5;z++)world.setBlockState(new BlockPos(radar.posX+x,79,radar.posZ+z),net.minecraft.init.Blocks.STONE.getDefaultState(),2);radar.setLegacyPower(radar.getEnergyCapacity());radar.setDeployed(true);check("actual_radar_spawn",world.spawnEntity(radar),"9S18 native emitter");}
        if(tick==60)blind=incoming(StrategicSystemProfile.TOPOL_M,"abm-blue",0);
        if(tick==110){check("friendly_no_shot",shots.isEmpty() && cores.stream().allMatch(c->c.phase==0),"real radar, same team");blind.setDead();}
        if(tick==120){targets.add(incoming(StrategicSystemProfile.TOPOL_M,"abm-red",0));check("tier_four_target",MissileTrackingService.getThreatTier(targets.get(0))==4,"silo threat classification");check("tiers_one_to_three_refuse",!MissileTrackingService.canInterceptorEngage(targets.get(0),3,1600),"tier gates protected");}
        if(tick%20==0 && targets.size()>0 && tick<450){EntityStrategicMissile target=targets.get(0);Vec3d origin=new Vec3d(anchor.getX()+.5,83,anchor.getZ()+.5);System.out.println("SILOABMQA diagnostic y="+target.posY+" reachable="+SiloDefense.reachable(target,origin,140)+" radar="+MissileTrackingService.hasDefenseContact(world,target,origin,"abm-blue",true)+" radarPos="+radar.getPositionVector()+" visible="+AirDefenseVisibility.visible(world,radar.getPositionVector().addVector(0,3,0),target)+" deployed="+radar.getDeployment()+" contacts="+radar.getLegacyContacts()+" teams="+radar.getOwnerTeam()+"/"+target.getOwnerTeam()+" state="+cores.get(0).status);}
        if(tick==200){check("radar_linked",MissileTrackingService.linkedRadarCount(world,anchor.getX(),83,anchor.getZ(),"abm-blue")>0,"actual network link");check("hatch_opens_before_flight",cores.stream().anyMatch(c->c.phase==1),cores.stream().map(c->c.status).collect(java.util.stream.Collectors.toList()));}
        for(EntitySiloInterceptor shot:shots)if(!shot.isDead && tick%5==0){JsonObject row=new JsonObject();row.addProperty("tick",tick);row.addProperty("y",shot.posY);row.addProperty("cold",shot.isCold());row.addProperty("target",String.valueOf(shot.targetUuid()));trace.add(row);}
        if(tick==500){check("single_target_single_shot",shots.size()==1,shots.size());check("topol_intercepted",targets.get(0).isFallingDebris(),targets.get(0).getLegacyState());check("charge_once",cores.stream().mapToLong(c->c.getPower()).sum()==1_800_000,"one 200k launch");for(Entity target:targets)target.setDead();}
        if(tick==620){for(TileEntityMissileSilo c:cores){c.setInventorySlotContents(0,new ItemStack(WarTechContent.SILO_INTERCEPTOR));c.setPower(1_000_000);}targets.clear();targets.add(incoming(StrategicSystemProfile.ORESHNIK,"abm-red",0));targets.add(incoming(StrategicSystemProfile.ORESHNIK,"abm-red",32));}
        if(tick==1050){check("combined_raid_two_more_shots",shots.size()==3,shots.size());check("both_oreshniks_intercepted",targets.stream().allMatch(EntityStrategicMissile::isFallingDebris),targets.stream().map(EntityStrategicMissile::getLegacyState).collect(java.util.stream.Collectors.toList()));check("two_charges_once",cores.stream().allMatch(c->c.getPower()==800000 && c.getStackInSlot(0).isEmpty()),"200k each");DefenseBattleLog log=PlanningWorldData.get(world).defense(PlanningAccessPolicy.scope(owner));NBTTagCompound stats=log.summary("");check("defense_report_matches",stats.getInteger("Launched")==3 && stats.getInteger("Intercepted")==3 && stats.getInteger("Failed")==0,stats);check("no_strategic_attack_queue",StrategicFlightData.get(world).writeToNBT(new NBTTagCompound()).getTagList("Flights",10).tagCount()==0,"ABM has no strike warheads");for(Entity target:targets)target.setDead();}
        if(tick==1100){for(TileEntityMissileSilo c:cores){c.setInventorySlotContents(0,new ItemStack(WarTechContent.SILO_INTERCEPTOR));c.setPower(1_000_000);}
            tel=new EntityStrategicTel(world,StrategicSystemProfile.TOPOL_M);tel.setOwnerIdentity(enemy.getUniqueID(),"abm-red");tel.setPosition(anchor.getX()+400,80,anchor.getZ());pin((int)tel.posX,(int)tel.posZ);for(int x=-8;x<=8;x++)for(int z=-8;z<=8;z++)world.setBlockState(new BlockPos(tel.posX+x,79,tel.posZ+z),net.minecraft.init.Blocks.STONE.getDefaultState(),2);tel.setMissileLoaded(true);tel.setGuidanceTarget(anchor.getX()+80,80,anchor.getZ());tel.setDeployed(true);enemy.capabilities.isCreativeMode=true;check("mobile_tel_spawn",world.spawnEntity(tel),"real Topol TEL");}
        if(tick==1210)check("mobile_tel_launch",tel.beginLaunchFromDetonator(enemy),"native deployed launcher and original handoff");
        if(tick==1480){check("mobile_boost_observed",mobileBoost!=null && !mobileBoost.isSiloOrigin(),mobileBoost==null?"absent":mobileBoost.getVisualId());check("mobile_midcourse_observed",StrategicFlightData.get(world).writeToNBT(new NBTTagCompound()).getTagList("Flights",10).tagCount()==1,"real virtual flight queue");}
        if(tick>1480 && tick%20==0 && mobileReentry!=null){Vec3d origin=new Vec3d(anchor.getX()+.5,83,anchor.getZ()+.5);System.out.println("SILOABMQA fullflight tick="+tick+" target="+mobileReentry.getPositionVector()+" dead="+mobileReentry.isDead+" tier="+MissileTrackingService.getThreatTier(mobileReentry)+" team="+mobileReentry.getOwnerTeam()+" radarDead="+radar.isDead+" radarPos="+radar.getPositionVector()+" radarHealth="+radar.getHealthValue()+" radarPower="+radar.getLegacyPower()+" contacts="+radar.getLegacyContacts()+" linked="+MissileTrackingService.linkedRadarCount(world,origin.x,origin.y,origin.z,"abm-blue")+" contact="+MissileTrackingService.hasDefenseContact(world,mobileReentry,origin,"abm-blue",true)+" visible="+AirDefenseVisibility.visible(world,radar.getPositionVector().addVector(0,3,0),mobileReentry)+" reachable="+SiloDefense.reachable(mobileReentry,origin,140)+" states="+cores.stream().map(c->c.status+"/"+c.phase+"/"+c.cooldown).collect(java.util.stream.Collectors.toList()));if(!mobileReentry.isDead && !mobileReentry.isFallingDebris() && mobileReentry.posY<150){check("missed_before_impact",false,"QA prevents nuclear terrain damage after a missed intercept");mobileReentry.setDead();}}
        if(tick==2150){check("mobile_reentry_high_enough",mobileEntryHeight,"entry at >=900 for either origin");check("mobile_reentry_tier4",mobileReentry!=null && !mobileReentry.isSiloOrigin() && mobileReentry.getStrategicSystem().getDefenseTier()==4,"origin false, Topol tier4");check("mobile_tel_topol_intercepted",mobileReentry!=null && mobileReentry.isFallingDebris(),mobileReentry==null?"no reentry":mobileReentry.getLegacyState());check("mobile_tel_one_more_shot",shots.size()==4,shots.size());check("mobile_tel_one_charge",cores.stream().mapToLong(c->c.getPower()).sum()==1_800_000,"one 200k launch");DefenseBattleLog log=PlanningWorldData.get(world).defense(PlanningAccessPolicy.scope(owner));NBTTagCompound stats=log.summary("");check("complete_defense_report",stats.getInteger("Launched")==4 && stats.getInteger("Intercepted")==4 && stats.getInteger("Failed")==0,stats);for(Entity entity:new ArrayList<>(world.loadedEntityList))if(entity instanceof EntityStrategicMissile || entity instanceof EntitySiloInterceptor)entity.setDead();tel.setDead();radar.setDead();for(ForgeChunkManager.Ticket ticket:pins)ForgeChunkManager.releaseTicket(ticket);}
        if(tick==2210){String resources=MissileChunkLoader.diagnostics(world);check("flight_resources_released",resources.contains("flights=0/") && resources.contains("queue=0 chunks/0 owners"),resources);JsonObject out=new JsonObject();out.addProperty("complete",true);out.add("cases",cases);out.add("failures",new Gson().toJsonTree(failures));out.addProperty("resources",resources);Files.write(Paths.get("flightqa-report.json"),new GsonBuilder().setPrettyPrinting().create().toJson(out).getBytes(StandardCharsets.UTF_8));Files.write(Paths.get("silo-abm-trace.json"),new Gson().toJson(trace).getBytes(StandardCharsets.UTF_8));world.getMinecraftServer().initiateShutdown();}
    }
}
